sed -i '272i\    private const val KEY_AUTO_REPLY_TOKENS = "KEY_AUTO_REPLY_TOKENS"\n    fun getAutoReplyTokens(): Int = getInt(KEY_AUTO_REPLY_TOKENS, 0)\n    fun addAutoReplyTokens(amount: Int) {\n        val current = getAutoReplyTokens()\n        putInt(KEY_AUTO_REPLY_TOKENS, current + amount)\n    }\n    fun resetAutoReplyTokens() {\n        putInt(KEY_AUTO_REPLY_TOKENS, 0)\n    }\n' app/src/main/java/io/agents/pokeclaw/utils/KVUtils.kt
